"""Portable exact proof of three-pair reserved-anchor attachment.

The inference primitives derive from Linnet's two-exceptional checker, itself
following Aster's Boolean/Farkas/RUP method. No producing solver is imported.
See RESERVED_THREE_PAIRS.md for the theorem, encoding and limitations.
"""
from __future__ import annotations

import argparse
import base64
from collections import deque
from fractions import Fraction
from functools import lru_cache
from itertools import combinations, product
import json
from math import gcd
from pathlib import Path
import zlib

from reserved_singleton import validate_reserved
from swaps import ef1


@lru_cache(maxsize=1)
def graph():
    """Independently enumerate every (2,2,2,1) allocation and exchange."""
    states = []
    for first in combinations(range(7), 2):
        for second in combinations(sorted(set(range(7)) - set(first)), 2):
            for third in combinations(sorted(set(range(7)) - set(first) - set(second)), 2):
                a = [3] * 7
                for owner, bundle in enumerate((first, second, third)):
                    for g in bundle:
                        a[g] = owner
                states.append(tuple(a))
    states = tuple(states)
    index = {a: k for k, a in enumerate(states)}
    edges = []
    for k, a in enumerate(states):
        for x, y in combinations(range(7), 2):
            if a[x] == a[y]:
                continue
            b = list(a)
            b[x], b[y] = b[y], b[x]
            j = index[tuple(b)]
            if j > k:
                edges.append((k, j))
    return states, tuple(edges)


def need(condition, message):
    if not condition:
        raise ValueError(message)


def literal(value, size):
    need(type(value) is int and 0 < abs(value) <= size, "invalid propositional literal")
    return value


class Formulas:
    """Acyclic Boolean definitions and independently rebuilt mathematical premises."""

    def __init__(self, variables, states, edges, premises):
        self.variables = variables
        self.size = len(variables)
        self.atoms, self.names, self.ops, self.defs = {}, {}, {}, {}
        self.clauses = [(1,)]
        need(variables and variables[0] == ["true"], "variable one must be true")
        for k, spec in enumerate(variables[1:], 2):
            need(isinstance(spec, list) and spec, "invalid variable definition")
            kind = spec[0]
            if kind == "linear":
                need(len(spec) == 3 and type(spec[1]) is int and spec[1] in range(4), "invalid utility row")
                c = spec[2]
                need(len(c) == 7 and all(type(v) is int for v in c) and any(c), "invalid linear form")
                need(gcd(*c) == 1, "linear form is not primitive")
                key = spec[1], tuple(c)
                need(key not in self.atoms, "duplicate linear atom")
                self.atoms[key] = k
            elif kind in ("fair", "reach"):
                need(len(spec) == 2 and type(spec[1]) is int and spec[1] in range(len(states)), "invalid vertex variable")
                need(tuple(spec) not in self.names, "duplicate vertex variable")
                self.names[tuple(spec)] = k
            else:
                need(kind in ("and", "or", "iff") and len(spec) == 2, "unknown Boolean definition")
                args = tuple(literal(v, k - 1) for v in spec[1])
                need(len(args) >= 2 and (kind != "iff" or len(args) == 2), "invalid Boolean arity")
                key = kind, args
                need(key not in self.ops, "duplicate Boolean definition")
                self.ops[key], self.defs[k] = k, key
                if kind == "and":
                    self.clauses.extend((-k, v) for v in args)
                    self.clauses.append((k,) + tuple(-v for v in args))
                elif kind == "or":
                    self.clauses.extend((k, -v) for v in args)
                    self.clauses.append((-k,) + args)
                else:
                    a, b = args
                    self.clauses.extend(((-k, -a, b), (-k, a, -b), (k, a, b), (k, -a, -b)))
        self._premises(states, edges, premises)

    def combine(self, kind, args):
        args = tuple(args)
        if kind == "iff":
            a, b = args
            if a == b:
                return 1
            if a == -b:
                return -1
            args = tuple(sorted(args))
        else:
            args = set(args)
            if (kind == "and" and -1 in args) or (kind == "or" and 1 in args):
                return -1 if kind == "and" else 1
            args.discard(1 if kind == "and" else -1)
            if any(-a in args for a in args):
                return -1 if kind == "and" else 1
            args = tuple(sorted(args))
            if not args:
                return 1 if kind == "and" else -1
            if len(args) == 1:
                return args[0]
        need((kind, args) in self.ops, "missing definition of a mathematical premise")
        return self.ops[kind, args]

    def comparison(self, row, owned, good):
        c = tuple(owned.count(g) - int(g == good) for g in range(7))
        if not any(c):
            return 1
        divisor = gcd(*c)
        key = row, tuple(v // divisor for v in c)
        need(key in self.atoms, "missing utility comparison")
        return self.atoms[key]

    def _premises(self, states, edges, premises):
        need(isinstance(premises, list) and all(type(k) is int for k in premises)
             and len(set(premises)) == len(premises), "invalid premise indices")
        chosen = set(premises)
        counter = 0

        def require(build):
            nonlocal counter
            if counter in chosen:
                self.clauses.append((build(),))
            counter += 1

        for i in range(4):
            for g in range(7):
                require(lambda i=i, g=g: self.comparison(i, [g], -1))
        for i in range(3):
            for g in range(7):
                if g != 6 and g not in range(i):
                    require(lambda i=i, g=g: self.comparison(i, [i], g))
        by_first = [[] for _ in states]
        for a, b in edges:
            by_first[a].append(b)
        for k, state in enumerate(states):
            def fairness(k=k, state=state):
                comparisons = []
                for i in range(4):
                    own = [g for g, a in enumerate(state) if a == i]
                    for j in range(3):
                        if i != j:
                            comparisons.append(self.combine("or", (
                                self.comparison(i, own, g) for g, a in enumerate(state) if a == j)))
                return self.combine("iff", (self.names["fair", k],
                                            self.combine("and", comparisons)))
            require(fairness)
            for j in by_first[k]:
                require(lambda k=k, j=j: self.combine("or", (
                    -self.combine("and", (self.names["fair", k], self.names["fair", j])),
                    self.combine("iff", (self.names["reach", k], self.names["reach", j])))))

            def exclude_greedy(k=k, state=state):
                bundles = [[g for g, a in enumerate(state) if a == i] for i in range(4)]
                options = []
                for first in product(*bundles[:3]):
                    picks = first + (bundles[3][0],) + tuple(
                        next(g for g in bundles[i] if g != first[i]) for i in range(3))
                    remaining, comparisons = set(range(7)), []
                    for i, g in zip((0, 1, 2, 3, 0, 1, 2), picks):
                        comparisons.extend(self.comparison(i, [g], h) for h in sorted(remaining) if h != g)
                        remaining.remove(g)
                    options.append(self.combine("and", comparisons))
                return self.combine("or", (-self.combine("or", options), -self.names["reach", k]))
            require(exclude_greedy)
        root = states.index((0, 1, 2, 0, 1, 2, 3))
        require(lambda: self.names["fair", root])
        require(lambda: self.names["reach", root])
        need(counter == 6975 and all(0 <= k < counter for k in chosen), "unknown premise index")


class BooleanDiagrams:
    """Reduced ordered decision diagrams certify Boolean tautologies exactly."""

    def __init__(self, definitions):
        self.definitions = definitions
        self.nodes, self.unique, self.values = [None, None], {}, {}
        self.negated, self.applied = {0: 1, 1: 0}, {}

    def node(self, v, low, high):
        if low == high:
            return low
        key = v, low, high
        if key not in self.unique:
            self.unique[key] = len(self.nodes)
            self.nodes.append(key)
        return self.unique[key]

    def negate(self, a):
        if a not in self.negated:
            v, low, high = self.nodes[a]
            self.negated[a] = self.node(v, self.negate(low), self.negate(high))
        return self.negated[a]

    def apply(self, op, a, b):
        a, b = sorted((a, b))
        key = op, a, b
        if key in self.applied:
            return self.applied[key]
        if op == "and" and a == 0:
            result = 0
        elif op == "or" and (a == 1 or b == 1):
            result = 1
        elif a == b:
            result = a
        elif (op == "and" and a == 1) or (op == "or" and a == 0):
            result = b
        else:
            av, al, ah = self.nodes[a]
            bv, bl, bh = self.nodes[b]
            v = min(av, bv)
            al, ah = (al, ah) if av == v else (a, a)
            bl, bh = (bl, bh) if bv == v else (b, b)
            result = self.node(v, self.apply(op, al, bl), self.apply(op, ah, bh))
        self.applied[key] = result
        return result

    def value(self, lit):
        if lit < 0:
            return self.negate(self.value(-lit))
        if lit == 1:
            return 1
        if lit not in self.values:
            if lit not in self.definitions:
                result = self.node(lit, 0, 1)
            else:
                op, args = self.definitions[lit]
                xs = [self.value(v) for v in args]
                if op == "iff":
                    a, b = xs
                    result = self.apply("or", self.apply("and", a, b),
                                        self.apply("and", self.negate(a), self.negate(b)))
                else:
                    result = 1 if op == "and" else 0
                    for v in xs:
                        result = self.apply(op, result, v)
            self.values[lit] = result
        return self.values[lit]

    def tautology(self, clause):
        result = 0
        for v in clause:
            result = self.apply("or", result, self.value(v))
        return result == 1


class Propagation:
    """Two watched literals implement reverse unit propagation (RUP)."""

    def __init__(self):
        self.clauses, self.positions, self.units, self.watch = [], [], [], {}
        self.empty = False

    def add(self, clause):
        clause = tuple(sorted(set(clause)))
        if any(-v in clause for v in clause):
            return
        k = len(self.clauses)
        self.clauses.append(clause)
        if not clause:
            self.empty = True
        if len(clause) < 2:
            self.units.extend(clause)
            self.positions.append(None)
        else:
            self.positions.append([0, 1])
            for v in clause[:2]:
                self.watch.setdefault(v, set()).add(k)

    def contradiction(self, assumed_clause):
        if self.empty:
            return True
        assigned = set()
        queue = self.units + [-v for v in assumed_clause]
        while queue:
            v = queue.pop()
            if v in assigned:
                continue
            if -v in assigned:
                return True
            assigned.add(v)
            for k in list(self.watch.get(-v, ())):
                clause, positions = self.clauses[k], self.positions[k]
                slot = 0 if clause[positions[0]] == -v else 1
                other = clause[positions[1 - slot]]
                if other in assigned:
                    continue
                replacement = next((j for j, x in enumerate(clause)
                                    if j not in positions and -x not in assigned), None)
                if replacement is not None:
                    self.watch[-v].remove(k)
                    self.watch.setdefault(clause[replacement], set()).add(k)
                    positions[slot] = replacement
                elif -other in assigned:
                    return True
                else:
                    queue.append(other)
        return False

def verify_certificate(data):
    """Refute a cut between a reserved start and every fixed-schedule greedy state."""
    need(data.get("format") == "reserved-three-pairs-rup-v1", "unknown proof format")
    states, edges = graph()
    need(tuple(map(tuple, data["states"])) == states and tuple(map(tuple, data["edges"])) == edges,
         "certificate graph differs from the complete graph")
    formulas = Formulas(data["variables"], states, edges, data["premises"])
    propagation = Propagation()
    for clause in formulas.clauses:
        propagation.add(clause)
    def checked_clause(clause):
        need(isinstance(clause, list), "proof clauses must be lists")
        return tuple(literal(v, formulas.size) for v in clause)
    for clause, weights in data["theory"]:
        clause = checked_clause(clause)
        need(all(abs(v) in {value for value in formulas.atoms.values()} for v in clause), "nonlinear theory clause")
        total = [[Fraction(0) for _ in range(7)] for _ in range(4)]
        strict = False
        for index, numerator, denominator in weights:
            need(type(index) is int and index in range(len(clause)) and type(numerator) is int
                 and type(denominator) is int and numerator > 0 and denominator > 0, "invalid positive multiplier")
            v = clause[index]
            _, row, coefficients = formulas.variables[abs(v) - 1]
            factor = Fraction(numerator, denominator) * (-1 if v > 0 else 1)
            for g, coefficient in enumerate(coefficients):
                total[row][g] += factor * coefficient
            strict |= v > 0
        need(strict and not any(value for row in total for value in row), "linear contradiction does not sum to zero")
        propagation.add(clause)
    diagrams = BooleanDiagrams(formulas.defs)
    for clause in data["tautologies"]:
        clause = checked_clause(clause)
        need(diagrams.tautology(clause), "claimed Boolean tautology is false")
        propagation.add(clause)
    proof = data["proof"]
    need(proof and proof[-1] == [], "proof must conclude with the empty clause")
    for k, clause in enumerate(proof):
        clause = checked_clause(clause)
        need(propagation.contradiction(clause), f"RUP step {k} is not justified")
        propagation.add(clause)
    return {"vertices": len(states), "edges": len(edges), "variables": formulas.size, "premises": len(data["premises"]),
            "linear_lemmas": len(data["theory"]), "Boolean_lemmas": len(data["tautologies"]),
            "RUP_steps": len(proof)}


@lru_cache(maxsize=1)
def certificate():
    return json.loads(zlib.decompress(base64.b85decode(_PROOF)))


@lru_cache(maxsize=1)
def verified_proof():
    return verify_certificate(certificate())


def _witness(u, state):
    bundles = [[g for g, a in enumerate(state) if a == i] for i in range(4)]
    for first in product(*bundles[:3]):
        picks = first + (bundles[3][0],) + tuple(
            next(g for g in bundles[i] if g != first[i]) for i in range(3))
        remaining = set(range(7))
        for a, g in zip((0, 1, 2, 3, 0, 1, 2), picks):
            if any(u[a][h] > u[a][g] for h in remaining):
                break
            remaining.remove(g)
        else:
            return tuple(zip((0, 1, 2, 3, 0, 1, 2), picks))
    return None


def reserved_path(u, start, singleton, anchors):
    """Return a fair path and final greedy witness for three reserved pairs."""
    validate_reserved(u, start, singleton, anchors)
    if len(u) != 4 or len(start) != 7:
        raise ValueError("this certificate requires three pairs and one singleton")
    agents = tuple(a for a, _ in anchors) + (singleton,)
    goods = tuple(g for _, g in anchors) + tuple(
        next(g for g, a in enumerate(start) if a == owner and g != anchor)
        for owner, anchor in anchors) + (start.index(singleton),)
    values = tuple(tuple(u[a][g] for g in goods) for a in agents)
    states, edges = graph()
    root = states.index((0, 1, 2, 0, 1, 2, 3))
    verified_proof()
    adjacent = [[] for _ in states]
    for a, b in edges:
        adjacent[a].append(b)
        adjacent[b].append(a)
    previous, queue = {root: None}, deque([root])
    while queue:
        k = queue.popleft()
        witness = _witness(values, states[k])
        if witness is not None:
            break
        for j in adjacent[k]:
            if j not in previous and ef1(values, states[j]):
                previous[j] = k
                queue.append(j)
    else:
        raise AssertionError("verified attachment certificate has no numeric path")
    route = []
    while k is not None:
        lifted = [-1] * 7
        for g, owner in enumerate(states[k]):
            lifted[goods[g]] = agents[owner]
        route.append(tuple(lifted))
        k = previous[k]
    return list(reversed(route)), tuple((agents[a], goods[g]) for a, g in witness)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--export", type=Path)
    parser.add_argument("--certificate", type=Path)
    args = parser.parse_args()
    data = json.loads(args.certificate.read_text()) if args.certificate else certificate()
    result = verify_certificate(data)
    if args.export:
        args.export.write_text(json.dumps(data, separators=(",", ":")) + "\n")
    print(json.dumps({"status": "verified", **result}, sort_keys=True))


